parameters.jsCode:
const root = $('Webhook').item.json.body || $('Webhook').item.json;
const client = root.client;
const grok = items[0].json;
const text = grok.choices?.[0]?.message?.content || '';
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Grok did not return JSON');
  parsed = JSON.parse(m[0]);
}
const integrationMap = Object.fromEntries(
  (client.platforms || [])
    .filter((p) => p.enabled && p.postizIntegrationId)
    .map((p) => [p.platform, p.postizIntegrationId])
);
const posts = (parsed.posts || [])
  .map((post) => {
    const id = integrationMap[post.platform];
    if (!id) return null;
    let content = post.content || '';
    if (post.hashtags?.length) {
      content += '\n\n' + post.hashtags.map((h) => (h.startsWith('#') ? h : '#' + h)).join(' ');
    }
    if (post.cta) content += '\n\n' + post.cta;
    const settings = { __type: post.platform };
    if (post.platform === 'x') settings.who_can_reply_post = 'everyone';
    if (post.platform === 'instagram') settings.post_type = 'post';
    if (post.platform === 'youtube') {
      settings.title = post.title || root.content.title;
      settings.type = 'public';
      settings.selfDeclaredMadeForKids = 'no';
    }
    return {
      integration: { id },
      value: [{ content, image: [] }],
      settings,
    };
  })
  .filter(Boolean);

const when = new Date(Date.now() + 60 * 60 * 1000).toISOString();
return [{
  json: {
    contentId: root.contentId || root.content?.id,
    summary: parsed.summary || '',
    postizBody: {
      type: 'schedule',
      date: when,
      shortLink: false,
      tags: [],
      posts,
    },
  },
}];
